const html: string = "<div>\n        <p>\n          <h2>1. AVUSTRALYA FUTBOLU</h2>\n        </p>\n        <p>\n          <span>1. Bahis şirketi bahisleri kabul eder:</span>\n        </p>\n        <p>\n          <span>\n            - normal süre için 80 dakika (20 dakikanın dörtte biri veya iki yarısı)\n            her biri 40 dakika)\n          </span>\n        </p>\n        <p>\n          <span>\n            - normal ve uzatma süreleri için (\"Dahil\" işaretiyle)\n            ekstra zaman\")\n          </span>\n        </p>\n        <p>\n          <span>\n            Bahisçi yanlış sürenin hatalı olmasından sorumlu değildir.\n            maç. “Spor” ve Canlı bölümlerdeki veriler gösterge niteliğindedir.\n            Müşteri kuralları resmi kaynaklara göre kontrol etmelidir.\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Maç 80 dakikadan önce durdurulursa tüm bahisler hesaplanır\n            Bahis sonuçlarının açıklanma durumu hariç, 1 oranla\n            maçın kesintiye uğradığı anda zaten açıkça belirlendi.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            3. Maçın oynanacağı mekanın değişmesi durumunda oynanan bahisler\n            ev sahibi takımın aynı takımda kalması koşuluyla yürürlükte kalır.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            4. \"İlk golü atar\" bahisi Bir oyuncu katılmadıysa\n            Maçta veya ilk gol atıldıktan sonra sahaya girildiğinde,\n            bahisler geçersiz sayılır. Değiştirilen oyunculara yapılan bahisler\n            veya ilk gol atılmadan oyundan atılırsa kaybeder. Eğer\n            İlk golü, kendisine bahis oranı teklif edilmeyen bir oyuncu atarsa,\n            o zaman diğer oyunculara yapılan tüm bahisler, bir teklif verilmediği sürece kaybeder.\n            \"Başka herhangi bir oyuncu\" bahis seçeneği. Maç daha önce yarıda kesilmiş olsaydı\n            İlk gol atıldığında tüm bahisler iptal edilir.\n            \n          </span>\n        </p>\n        <p>\n          <strong>2. AMERİKAN FUTBOLU</strong>\n        </p>\n        <p>\n          <span>1. Bahis şirketi bahisleri kabul eder:</span>\n        </p>\n        <p>\n          <span>\n            - normal süre için (60 dakikalık oyun süresinin dörde bölünmesiyle)\n            15 dakika)\n          </span>\n        </p>\n        <p>\n          <span>\n            - normal ve uzatma süreleri için (\"Dahil\" işaretiyle)\n            ekstra zaman\")\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Maç başlamış ancak tamamlanmamışsa tüm bahisler geçerli sayılacaktır.\n            Sonucu kesin olan bahisler hariç, 1 oranla sonuçlandırılır\n            maç durduruluncaya kadar belirlenir.\n          </span>\n        </p>\n        <p>\n          <span>\n            3. Bahislerin geçerli sayılması için oyunun en az sürmesi gerekir.\n            55 dakika. Bu durumda tüm bahisler sonuçlara göre hesaplanır.\n            o sırada maç yarıda kesildi.\n          </span>\n        </p>\n        <p>\n          <span>\n            4. Eğer takım \"Turnuvayı daha üst sırada bitirir\" bahisleri için\n            gruptan ayrılmaya hak kazanmıyor, bahisler şu şekilde hesaplanır:\n            gruptaki konumlarına göre. Ekipler bölgeyi işgal ederse\n            aynı yerlerde, bahisler hesaplanır\n          </span>\n        </p>\n        <p>\n          <span>\n            5. “En verimli çeyrek” bahisi. Eğer imkansızsa açıkça\n            en verimli çeyreği belirleyin (örneğin iki veya daha fazla)\n            Çeyrek aynı skorla bitti), bu tür çeyreklere ilişkin bahisler sonuçlandırılır\n            1 oranla. Geriye kalan çeyreklere yapılan bahisler kaybeder.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            6. “En verimli yarı” bahisi. Her iki yarı da şu şekilde biterse\n            aynı skor, bahisler 1 oranla sonuçlandırılır.\n          </span>\n        </p>\n        <p>\n          <span>\n            7. Uzatmalar da dahil olmak üzere maçın berabere bitmesi durumunda bahisler\n            Takımlardan birinin veya diğerinin kazanması 1 oranla hesaplanır (bahis tutarları)\n            iade edilecektir). Toplamlar ve handikaplar aşağıdakilere göre hesaplanır:\n            maç sonuçları.\n          </span>\n        </p>\n        <p>\n          <strong>3. BADMINTON, MASA TENİSİ, PLAJ VOLEYBOLU</strong>\n        </p>\n        <p>\n          <span>\n            1. Maçın başlaması gecikirse veya ertelenirse tüm bahisler kalır\n            maçın veya turnuvanın sonuna kadar veya katılıma kadar geçerlidir\n            katılımcılardan birinin.\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Maçın ret veya diskalifiye nedeniyle kesintiye uğraması halinde\n            Takımlardan bir tanesine ilişkin tüm bahisler 1 oranla sonuçlandırılır, ancak bu oranlar\n            Bunun sonucu, maçın ne zaman durdurulduğuna göre açıkça belirlenir.\n            B Bu durumda maçın galibi üzerine oynanan bahisler sonuçlandırılır\n            1 oranla.\n          </span>\n        </p>\n        <p>\n          <span>\n            3. Sporcuların baş harflerindeki yazım hatalarından dolayı (örneğin, B. Smith)\n            A. Smith yerine) bahisleri iptal edilmez. Bu durumda,\n            oranlar geçerliliğini koruyor.\n          </span>\n        </p>\n        <p>\n          <span>\n            4. “Maçın Kazananı” bahisi. Bahiste belirtilen oyuncunun değiştirilmesi durumunda\n            Maç başlamadan önce tüm bahisler geçersizdir.\n          </span>\n        </p>\n        <p>\n          <span>\n            5. Badminton, masa tenisi, plaj tenisi handikapları ve toplamları\n            Voleybol “Set bazında handikap” haricinde puanla belirtilmelidir.\n            ve “Toplam setler”.\n          </span>\n        </p>\n        <p>\n          <span>\n            6. “Kazanan” bahisi. Turnuvada birinci olan sporcu (takım)\n            kazanan sayılır. Sporcu yarışmaya katılmayı reddederse\n            bir turnuva başlamadan önce, bahisler şu şekilde sonuçlandırılır:\n            oran 1.\n          </span>\n        </p>\n        <p>\n          <strong>4. BASKETBOL</strong>\n        </p>\n        <p>\n          <span>1. Bahis şirketi bahisleri kabul eder:</span>\n        </p>\n        <p>\n          <span>\n            - normal süre için (48 dakikalık oyun süresi, 12'lik 4 çeyrek\n            dakika veya 40 dakika oyun süresi, 10 dakikalık 4 çeyrek),\n            NCAA (Ulusal Üniversite Atletizm Birliği) - iki yarısı\n            20 dakika\n          </span>\n        </p>\n        <p>\n          <span>\n            - normal ve uzatma süreleri için (\"Dahil\" işaretiyle)\n            ekstra zaman\")\n          </span>\n        </p>\n        <p>\n          <span>\n            İstatistiksel bahisler aksi belirtilmediği sürece uzatmaları da içerir. Diğer\n            Bahis koşulları bahis bölümünde belirtilebilir.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            2. Maç başlamış ancak tamamlanmamışsa tüm bahisler\n            maç hariç 1 oranla hesaplanır\n            sonucu zaten belirlenmiş olan\n          </span>\n        </p>\n        <p>\n          <span>\n            3. Maçın 40 dakika sürmesi durumunda bahislerin geçerli sayılması için,\n            Oyun en az 35 dakika sürmelidir. Maç süresi ne zaman\n            Bahislerin geçerli sayılması için oyunun en az 48 dakika sürmesi gerekir\n            40 dakika. Bu gibi durumlarda, tüm bahisler aşağıdakilere göre hesaplanır:\n            maçın durdurulduğu andaki sonuçlar hakkında.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            4.NBA takımları sıralı bir şekilde (ev sahibi - misafir) listelenebilir,\n            ve tam tersi. Ters düzenleme durumunda geri ödeme yapılmaz\n            bahislerde.\n          </span>\n        </p>\n        <p>\n          <span>\n            5. Hazırlık (kupa, kulüp) basketbol müsabakalarının yönetmeliği netleştirildi\n            müşteri tarafından resmi kaynaklardan bağımsız olarak. Dostluk maçı ise\n            beraberlikle sonuçlandı (maç kuralları değişti), ardından kazanan üzerine bahisler yapıldı\n            1 oranla hesaplanır. Toplamlar ve handikaplar hesaplanır\n            Elde edilen sonuca göre.\n          </span>\n        </p>\n        <p>\n          <span>\n            6. Basketbol kupa maçlarında, toplam puana göre uzatma verilir.\n            İki maçın sonuçları yalnızca bahislerde dikkate alınır\n            bir sonraki tura, başka bir lige, galibine yükselirken\n            rekabet ve\n          </span>\n        </p>\n        <p>\n          <span>\n            7. Basketbol maçı berabere biterse, ekstra \"Olacak\" bahisi\n            zaman\" kazanır ve \"Uzatma süresi olmayacak\" bahisi kaybeder.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            8. “Spor” bölümündeki “İlk yarı/maç süresi” bahisinde\n            \"P\" galibiyet, \"X\" ise beraberlik anlamına gelir. Sonuç ilk olarak listelenir\n            Maçın ilk yarısı ve ardından normal sürenin sonucu.\n            Örneğin, W1W2, ilk takımın (W1) birinciyi kazanacağı anlamına gelir\n            Yarı oyun ve normal şartlarda ikinci takım (G2) maçı kazanacak\n          </span>\n        </p>\n        <p>\n          <span>\n            9. “En verimli çeyrek” bahisi. En etkili çeyrek ise\n            kesin olarak belirlenemez (iki veya daha fazla çeyrek\n            aynı sonuçla sona erdi), bu çeyreklere ilişkin bahisler sonuçlandırılır\n            oranı 1'dir. Diğer çeyreklere yapılan bahisler kaybeder (son puanlar\n            4. çeyrek belli oldu, sayılar, ekstralarda atılan puanlar\n            zaman dikkate alınmaz).\n          </span>\n        </p>\n        <p>\n          <span>\n            10. \"En verimli yarı\"ya bahis yapın. Her iki yarı da aynı şekilde biterse\n            sonuç olarak bahisler 1 oranla sonuçlandırılır (ikinci tur sonucunda\n            yarıda, uzatmalarda kazanılan puanlar dikkate alınmaz).\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            11. \"Takım... her iki yarıyı da kazanacak\" diye bahis yapın. İkincisinin sonucunda\n            yarıda, uzatmalarda kazanılan puanlar dikkate alınmaz.\n            Belirtildiği takdirde \"Takım... her iki yarıyı da kazanamayacak\" bahisi kazanır\n            takım en az bir yarı berabere kalır veya kaybeder.\n          </span>\n        </p>\n        <p>\n          <span>\n            12. “Her iki takım da 72,5 sayıdan fazla puan alır” bahisi. Bahis kazanır\n            Maç sırasında her iki takım da 73 veya daha fazla puan alırsa.\n          </span>\n        </p>\n        <p>\n          <span>\n            13. “Her iki takım da 72,5 sayıdan fazla puan alamayacak” bahisi.\n            En az bir takım belirtilen sonuca ulaşamazsa oran kazanır.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            14. \"Her çeyreğin toplamı 32,5 puanın üzerindedir\" bahisi.\n            Her çeyrekte atılan toplam puan sayısı eşitse oran kazanır\n            - 33 veya daha fazla.\n          </span>\n        </p>\n        <p>\n          <span>\n            15. “Çeyreklik handikap” bahisi. Örneğin, “2 Handikap\n            çeyrekler -2,5”. Final puanı 81:102 (17:22, 26:25, 18:20, 20:35),\n            çeyreklerdeki skorun 1:3 olduğu anlamına gelir (sırasıyla 0:1, 1:0, 0:1, 0:1).\n            Bahis kaybetti çünkü çeyrekte 2. takıma handikap uygulandıktan sonra\n            skor 1:0.5 olacaktır.\n          </span>\n        </p>\n        <p>\n          <span>\n            16. \"6-10 Skor Farkıyla Kazan\" bahisi, farkın oluşması durumunda kazanır\n            birincinin puanı ile ikincinin puanı arasındaki puan cinsinden\n            Takım 6 ile 10 puan arasında değişecek. Örnek: maç skoru (85:90),\n            2. takımın galibiyet sayısı farkı 5'tir, dolayısıyla bahis\n          </span>\n        </p>\n        <p>\n          <strong>5. BEYZBOL, SOFTBOL</strong>\n        </p>\n        <p>\n          <span>\n            1. Beyzbol maçlarına yapılan bahisler, aksi belirtilmedikçe normal sürelerde kabul edilir.\n            belirtti.\n          </span>\n        </p>\n        <p>\n          <span>\n            Kabul edilirken başlangıç atıcılarının isimleri dikkate alınır.\n            Belirli bir spor etkinliğinde isimlerin belirtilmesi durumunda bahisler. Her iki atıcı\n            Bahislerin geçerli olabilmesi için sahaya girmeli ve en az bir atış yapmalısınız.\n            geçerli sayılır. Herhangi bir nedenle listelenen atıcılardan herhangi biri bunu yaptıysa\n            sahaya çıkmazsanız tüm bahisler geçersiz sayılır. Atıcılara başlıyorsanız\n            listelenmemiş, kimin başladığına bakılmaksızın bahisler kabul edilir\n            sürahi vardır.\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Maçta ev sahibi takım, ne olursa olsun ikinci vuruş yapan takımdır.\n            oyunun bulunduğu yer.\n          </span>\n        </p>\n        <p>\n          <span>\n            3. Tüm bahisler resmi maç sonuçlarına göre sonuçlandırılır.\n            ekstra vuruşlar (parça maçına oynanan bahisler hariç).\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            4. En az beş bahis oynanırsa tüm bahisler geçerli kabul edilir\n            tam vuruş veya 4,5 vuruş. 4,5 vuruştan az oynanırsa, o zaman\n            aşağıdakiler hesaplanacaktır: zafere oynanan bahisler; bir sonrakine geçiş\n            sahne; sonuçları zaten açıkça belirlenmiş olan oranlar\n            maçın kesintiye uğradığı sırada. Bu maça ilişkin diğer tüm bahisler\n            ihtimallerle halledildi\n          </span>\n        </p>\n        <p>\n          <span>\n            5. Maç öncesi bahisler. Bir beyzbol maçı belirtilen saatte başlamazsa\n            zaman zaman ve resmi web sitesinde konuyla ilgili onay var\n            maçın ertelenmesi, ardından Bu maça ilişkin tüm bahisler\n          </span>\n        </p>\n        <p>\n          <span>\n            6. Maç sırasında yapılan bahisler. Maç durdurulursa (kesintiye uğrarsa)\n            ve 72 saat içinde devam ederse, bahisler 72 saatin sonuna kadar geçerli kalır.\n            maç. Maç 72 saat içinde tamamlanmazsa her şey\n            üzerine yapılan bahisler, aşağıdaki seçimler haricinde geçersizdir:\n            zaten kararlıydılar.\n          </span>\n        </p>\n        <p>\n          <span>\n            7. Softbol, beyzbolun oynanan bir versiyonu olan topla oynanan bir takım oyunudur.\n            Daha küçük bir alanda büyük bir topla oynayın. Resmi takım maçlarında\n            yedi vuruş oyna. Skor eşitse ek vuruşlar yapılır.\n            \n          </span>\n        </p>\n        <p>\n          <strong>6. BİATLON</strong>\n        </p>\n        <p>\n          <span>\n            1. “Daha yüksek bir yer alacak” bahisi. İki biatloncudan hangisinin seçilmesi\n            (veya takımlar) final sıralamasında daha yüksek bir yer alacaktır. Eğer her iki aday da\n            yarıştan çekilmek veya içlerinden birinin yarışa katılamayacak olması halinde,\n            bahisler 1 oranla sonuçlandırılır. Adaylardan herhangi biri\n            bitiş çizgisine ulaştığında tüm bahisler kaybedilmiş sayılır.\n            \n          </span>\n        </p>\n        <p>\n          <strong>7. KUTU, DÖVÜŞ SPORLARI</strong>\n        </p>\n        <p>\n          <span>\n            1. Dövüşün başlangıcı gong sesiyle belirtilir\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Dövüşün geçersiz sayılması veya herhangi bir nedenle durdurulması halinde\n            Kazanan belirlenene kadar tüm bahisler dikkate alınır\n            geçersiz. Dövüşün sonucu önceden belirlenmişse,\n            Bahisler açıklanan sonuçlara göre hesaplanır.\n          </span>\n        </p>\n        <p>\n          <span>\n            3. Tur sayısı değiştirilmişse, tur sonucuna oynanan bahisler\n            dövüş geçerli kalır ancak tur sayısına bahis yapılır\n            oranlarla halledilir\n          </span>\n        </p>\n        <p>\n          <span>\n            4. “Tur sayısı” bahisi. Dövüşteki tur sayısını tahmin etme\n            Bahis hesaplamasında yalnızca tamamlanan turlar dikkate alınır.\n          </span>\n        </p>\n        <p>\n          <span>\n            5. Eğer sporcu başlangıçtaki gong çalındıktan sonra ringe girmezse\n            raundun sonunda dövüş tamamlanmış sayılır\n          </span>\n        </p>\n        <p>\n          <strong>8. BİSİKLET YARIŞI</strong>\n        </p>\n        <p>\n          <span>\n            1. İlk sıralama yarışının başlangıcı başlangıç ​​olarak kabul edilir\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Düello bahisleri (sporcular veya takımlar). Bahislerin geçerli sayılması için her ikisi de\n            rakipler resmi başlangıç çizgisini geçmelidir.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            - Rakiplerden birinin herhangi bir nedenle yarışmadan çekilmesi durumunda,\n            rakibi kazanan ilan edildi\n          </span>\n        </p>\n        <p>\n          <span>\n            - Rakiplerden biri veya her ikisi de resmi çizgiyi geçemezse start,\n            bahisler 1 oranla hesaplanır\n          </span>\n        </p>\n        <p>\n          <span>\n            - Her iki yarışmacı da yarıştan çekilirse kazanan sürücü olur\n            en fazla turu tamamladı.\n          </span>\n        </p>\n        <p>\n          <span>\n            - Her iki sürücü de aynı turda elenirse bahisler sonuçlandırılır\n            1 oranla.\n          </span>\n        </p>\n        <p>\n          <span>\n            3. “Daha yüksek bir yer alacak” bahisi. İki yarışçıdan hangisinin seçilmesi\n            (veya takımlar) final sıralamasında daha üst sıralarda yer alacaktır.\n          </span>\n        </p>\n        <p>\n          <span>\n            4. Son sıralamada birden fazla bisikletçinin aynı süreye sahip olması durumunda,\n            kazanan, sıralamada daha yüksek olandır.\n          </span>\n        </p>\n        <p>\n          <strong>9. SU POLOSU</strong>\n        </p>\n        <p>\n          <span>\n            1. Tüm bahisler normal süredeki (32 dakika) sonuçlara göre sonuçlandırılır.\n            oyun süresi, 8 dakikalık dört çeyrek).\n          </span>\n        </p>\n        <p>\n          <span>\n            Bahis şirketi yanlış süre gösterimlerinden sorumlu değildir\n            oyunlar. “Spor” ve Canlı bölümlerde belirtilen veriler gösterge niteliğindedir.\n            Müşteri, sutopu kurallarını görevliyle kontrol etmelidir.\n            kaynaklar.\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Uzatmalar ve penaltı atışları yalnızca eleme bahisleri için geçerlidir.\n            zafer ve benzeri sonuçlar.\n          </span>\n        </p>\n        <p>\n          <span>\n            3. Maç başlamış ancak tamamlanmamışsa tüm bahisler geçerli sayılacaktır.\n            sonucu belirlenen bahisler hariç, 1 oranla sonuçlandırılır.\n            maç durduruluncaya kadar kesin olarak belirlendi.\n          </span>\n        </p>\n        <p>\n          <span>\n            4. Bahislerin geçerli sayılması için oyunun en az sürmesi gerekir.\n            30 dakika. Bu durumda tüm bahisler sonuçlara göre hesaplanır.\n            o sırada maç yarıda kesildi.\n          </span>\n        </p>\n        <p>\n          <strong>10. VOLEYBOL</strong>\n        </p>\n        <p>\n          <span>\n            1. Maç başlamış ancak tamamlanmamışsa tüm bahisler\n            maç hariç 1 oranla hesaplanır\n            sonucu zaten açıkça belirlenmiş olan\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Setin sonuna kadar oynanmaması durumunda daha önce alınan sonuçlar\n            Kesinti anında belirlenenler hesaplanırken sayılır\n            bahisler. Diğer tüm bahisler 1 oranla hesaplanır.\n            sonuna kadar oynandı ancak maç tamamlanmadı, bu sete bahisler\n            geçerli sayılır.\n          </span>\n        </p>\n        <p>\n          <span>\n            3. Voleybolda handikaplar ve toplamlar puanla gösterilir,\n            “Setlere göre handikap” ve “Setlerin toplamı” bahisleri hariç.\n          </span>\n        </p>\n        <p>\n          <span>\n            4. “Set bazında skor” bahisi. \"Spor\" bölümünde ilgili sütunlar\n            3:0, 3:1 vb. başlıklı.\n          </span>\n        </p>\n        <p>\n          <span>\n            5. \"3 (5 vb.) puan için yarış\" bahisine girin. Bunu yapacak ekibin seçilmesi\n            Set için belirlenen sayıda puanı ilk alan siz olun.\n            Eğer takım herhangi bir sebeple oyuna devam etmeyi reddederse veya\n            Rakibi belirtilen sayıda puan topladı, bahisler sonuçlandırılır\n            1 oranla.\n          </span>\n        </p>\n        <p>\n          <span>\n            6. \"Beraberlik bozma\" bahisi. Sonuç, beşincinin olup olmayacağıdır.\n            ayarlayın. Oran Beşinci olursa “eşitliği bozma olacak” kazanır\n          </span>\n        </p>\n        <p>\n          <strong>11. HENTBOL</strong>\n        </p>\n        <p>\n          <span>\n            1. Bahisler, ana maçın sonundaki sonuca göre sonuçlandırılır.\n            süresi (60 dakikalık oyun süresi, 30 dakikalık iki devre).\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Sadece uzatmalar ve penaltı atışları dikkate alınır\n            Aşağıdaki bahisler hesaplanırken: “Sonraki tura çıkış”, “Çıkış\n            başka bir lige”, “Zafer”\n          </span>\n        </p>\n        <p>\n          <span>\n            3. Oyun sırasında oynanan bahisler. Maç tamamlanmadıysa her şey\n            Bahisler, aşağıdaki sonuçlar haricinde 1 oranla sonuçlandırılır.\n            maç durdurulmadan önce açıkça belirlendi.\n          </span>\n        </p>\n        <p>\n          <strong>12.GOLF</strong>\n        </p>\n        <p>\n          <span>\n            1. Büyük golf turnuvaları üç veya dört gün sürer. Genel\n            delik sayısı genellikle 72'dir.\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Oyuncunun oyuna katılımcı olarak kabul edilebilmesi için:\n            ilk darbeyi vur. Golfçü oynamaya devam etmeyi reddederse, tüm\n            Bahisler onun kaybetmesi üzerine.\n          </span>\n        </p>\n        <p>\n          <span>\n            3. “Turnuvada kazan” bahisi. Golfçü birinci oldu\n            turnuva kazanan olarak kabul edilir. Kazanan belirlendi\n            eğer böyle bir aşama sağlanmışsa, play-off sonuçlarına göre\n            Kurallara göre turnuva.\n          </span>\n        </p>\n        <p>\n          <strong>13. DARTLAR</strong>\n        </p>\n        <p>\n          <span>\n            1. Maç bahisleri. Bir maç başlamış ancak tamamlanmamışsa,\n            bir sonraki tura yükselen oyuncu kazanan olarak kabul edilir.\n            Ancak belirli bir set, etap ve handikap için oranlar\n            çünkü özel bahisler, bahsin sonucu belli olmadığı sürece geçersiz olacaktır.\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Dart maçlarındaki handikaplar ve toplamlar, aşağıdaki durumlarda setler halinde gösterilir:\n            “Spor” bölümünde başka hiçbir şey belirtilmemiştir. Maksimum\n            tek yaklaşımda üç atışın sonucu mümkün\n          </span>\n        </p>\n        <p>\n          <strong>14. Kıvrılma</strong>\n        </p>\n        <p>\n          <span>\n            1. Curling maçlarına yapılan bahisler, aksi belirtilmedikçe ilave sonuçları da içerir\n            belirtti. Oyun 10 sondan oluşur. On el beraberlikten sonra ekstra bir puan verilirse\n            sonu oynanır. Ekstra sonda kazanan maçın galibi ilan edilir.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            2. Evde bir veya iki taş yoksa\n            evin merkezine en yakın rakipler aynı durumda\n            evin merkezine olan mesafe, son\n          </span>\n        </p>\n        <p>\n          <span>\n            3. Maç başlamış ancak tamamlanmamışsa tüm bahisler\n            maç hariç 1 oranla hesaplanır\n            sonucu zaten belirlenmiş olan\n          </span>\n        </p>\n        <p>\n          <span>\n            4. Tüm bahisler en az beş tam endov olması durumunda geçerlidir. Bu durumda hepsi\n            Bahisler, maçın durdurulduğu andaki sonuca göre hesaplanır.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            5. Bir takım her şeyi açıklamazsa, skor ne olursa olsun kaybeder\n            Taşlarınızı zamanında atın (bir uçta takımlar sırayla serbest bırakılır)\n            sekiz taş).\n          </span>\n        </p>\n        <p>\n          <span>\n            6. Tüm bahisler, ek bahisler de dahil olmak üzere resmi sonuçlara göre sonuçlandırılır.\n            sona erer (parça karşılaşmalarına oynanan bahisler hariç).\n            \n          </span>\n        </p>\n        <p>\n          <strong>15. KRİKET</strong>\n        </p>\n        <p>\n          <span>\n            1. Bahisler, tarafından açıklanan resmi sonuçlara göre sonuçlandırılır.\n            bu maçın veya turnuvanın organizatörleri.\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Maçın yarıda kesilmesi ve tamamlanmaması durumunda bahisler\n            istisna dışında 1 oranla hesaplanır\n            o zamana kadar açıkça belirlenen sonuçların\n          </span>\n        </p>\n        <p>\n          <span>\n            3. Maçın galibi D/L yöntemiyle belirlenirse bahisler\n            \"1x2\" ve \"Maçın Kazananı\" sonuçlarında; göre hesaplanır\n            D/L yönteminin sonuçlarına göre. Diğer sonuçlar hesaplanır\n            gerçek maça göre\n          </span>\n        </p>\n        <p>\n          <span>\n            4. “En İyi Vurucu” bahisi. En yüksek puana sahip olan oyuncu numarayı kazanır\n            maç başına koşu sayısı.\n          </span>\n        </p>\n        <p>\n          <span>\n            5. “En İyi Atıcı” bahisi. En yüksek puana sahip olan oyuncu numarayı kazanır\n            maç başına wicket sayısı. Bu gösterge eşitse bir sonraki kriter\n            ECON'dur - en çok wicket'e sahip olan ve en az ECON kazanan oyuncu.\n            Oyuncuların aldığı wicket sayısı ve ECON sayısı aynıysa,\n            En iyi atıcı kaçırılan koşu sayısına göre belirlenir.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            6. İlk X over üzerine “Bireysel Toplam Koşular” bahisi. D/L yöntemi durumunda,\n            Bahis, maç öncesinde tamamlanan fazlalıklar üzerinden hesaplanır.\n            maçın sonu.\n          </span>\n        </p>\n        <p>\n          <strong>16. PLAJ FUTBOLU</strong>\n        </p>\n        <p>\n          <span>\n            1. Tüm bahisler ana maçın sonundaki sonuca göre sonuçlandırılır.\n            süresi (36 dakikalık oyun süresi, 12 dakikalık üç periyot)\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Bahis şirketi yanlış bilgilerden sorumlu değildir\n            maçın süresi.\n          </span>\n        </p>\n        <p>\n          <span>\n            3. Canlı veya “Spor” bölümlerinde belirtilen veriler yaklaşık değerlerdir.\n            Müşteri resmi kaynaklardaki kuralları kontrol etmelidir.\n          </span>\n        </p>\n        <p>\n          <strong>17. ragbi</strong>\n        </p>\n        <p>\n          <span>\n            1. Tüm bahisler ana maçın sonundaki sonuca göre sonuçlandırılır.\n            süre (80 dakika oyun süresi, 40 dakikalık iki yarı).\n          </span>\n        </p>\n        <p>\n          <span>\n            Bahis şirketi yanlış sürenin hatalı olmasından sorumlu değildir.\n            maç. Canlı veya “Spor” bölümlerinde belirtilen veriler,\n            gösterge niteliğinde. Müşteri resmi kaynaklardaki kuralları kontrol etmelidir.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            2. Sadece uzatmalar ve penaltı atışları dikkate alınır\n            “Sonraki tura ilerleme” ve “Kazanma” bahislerini hesaplarken\n          </span>\n        </p>\n        <p>\n          <span>\n            3. Bahislerin geçerli olabilmesi için maçın oynanmış olması gerekmektedir. tamamen hariç\n            tarihine kadar sonucu kesin olarak belirlenmiş olan bahisler için\n            maç durduruldu.\n          </span>\n        </p>\n        <p>\n          <strong>18. Kabak</strong>\n        </p>\n        <p>\n          <span>\n            1. Maç başlamış ancak herhangi bir nedenle tamamlanmamışsa (örn.\n            örneğin, bir oyuncunun reddedilmesi veya diskalifiye edilmesi durumunda) aşağıdaki sonuçlar ortaya çıkar:\n            maç kesildiğinde zaten açıkça tanımlanmıştı\n            (örneğin ilk oyunun sonucu, ilk oyunun toplamı,\n            vb.), oranlar hesaplanırken sayılır. Diğer tüm bahisler\n            şunlardan hesaplanır:\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Spor müsabakasını düzenleyenlerin kararına göre,\n            oyun sayısı üç ila beş arasında değişebilir ve maç\n            takımlardan birinin zaferine kadar devam etmek\n          </span>\n        </p>\n        <p>\n          <strong>19. BİLARDO</strong>\n        </p>\n        <p>\n          <span>\n            1. Maç bahisleri. Maçın kesilmesi durumunda pas veren oyuncu\n            Bir sonraki turda en az bir kare olması durumunda kazanan kabul edilir.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            2. Çerçeve bahisleri, handikap, özel bahisler. Bahis düşünüldü\n            geçerli, belirlemek için gerekli tüm çerçeveler tamamlanmalıdır\n            maçın galibi. Kazanan herhangi bir nedenle belirlendiyse\n            maç bitmeden önce tüm bahisler çerçeveler ve handikaplar üzerine yapılır,\n            özel bahislerin yanı sıra 1 oranla sonuçlandırılır; ancak\n            sonucu zaten açıkça tanımlanmış olan bahisler için.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            3. Eğer oyuncu herhangi bir karede hükmen kaybederse handikap bahisleri yapılır.\n            Bu çerçevede toplamlar 1 oranla hesaplanır.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            4. \"Cebe atılan ilk top mavidir\" diye bahis yapın. İlk olursa bahis kazanır\n            Kurallara göre cebe atılan topun rengi mavidir (top renkleri:\n            sarı, yeşil, kahverengi, mavi, pembe, siyah).\n          </span>\n        </p>\n        <p>\n          <strong>20. TENİS</strong>\n        </p>\n        <p>\n          <span>\n            1. Eğer bir oyuncu daha önce katılmayı reddederse (veya diskalifiye edilirse)\n            Maçın başlangıcında bahisler iade edilir.\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Maçın başlaması gecikirse veya maç ertelenirse\n            Herhangi bir sebepten dolayı tüm bahisler maç sonuna kadar geçerli kalır.\n            veya maçın yapıldığı turnuva\n          </span>\n        </p>\n        <p>\n          <span>3. Bahisler aşağıdaki durumlarda geçerli kalır:</span>\n        </p>\n        <p>\n          <span>- kortların yüzeyinin değiştirilmesi</span>\n        </p>\n        <p>\n          <span>- mekan değişikliği</span>\n        </p>\n        <p>\n          <span>- Kapalı kortun açık kortla değiştirilmesi</span>\n        </p>\n        <p>\n          <span>\n            4. Red veya diskalifiye nedeniyle tenis maçı yarıda kesilirse\n            oyuncu, maç başlamadan önce oynanan tüm bahisler iade edilir\n            (1 oranla hesaplanmıştır). Canlı bahisler de geçersizdir (hesaplanan\n            1 oranla), sonuçların sonuçları hariç\n            maç durdurulduğunda zaten belirlenmişti.\n          </span>\n        </p>\n        <p>\n          <span>\n            5. Bir tenis maçının handikapı ve toplamı belirtilir\n          </span>\n        </p>\n        <p>\n          <span>\n            6. Herhangi bir nedenle oyun tamamlanmazsa (örneğin;\n            maç kesintiye uğradı ve tamamlanmadı, oyuncu devam etmeyi reddediyor\n            Oynanması veya diskalifiye edilmesi vb.), bu oyuna ilişkin bahisler şu şekilde sonuçlandırılır:\n            oran 1.\n          </span>\n        </p>\n        <p>\n          <span>\n            7. Karar setindeki tenis maçlarında sizi hangisinde kazanacağınız\n            need to win 10 points, the handicap and total are calculated by points,\n            and The entire match deciding set is counted as 1 game. Örneğin,\n            Grönefeld/Peshke – Niculescu/Zakopalova maçı. Toplamdan daha azına bahis yapın\n            21.5. 6:3, 3:6, 4:10 puan toplayın. Üçüncü set bir olarak kabul edilir\n            oyun. Toplam 6 + 3 + 3 + 6 + 1 = 19 olur.\n          </span>\n        </p>\n        <p>\n          <span>\n            8. \"Şampiyon eşitlik bozma\" veya \"süper\" eşitlik bozma olarak işaretlenen tenis maçlarında\n            Tüm maçın handikapı ve toplamı şu şekilde hesaplanacaktır:\n            puan dikkate alındığında\n          </span>\n        </p>\n        <p>\n          <span>\n            Örneğin Grönefeld/Peshke – Niculescu/Zakopalova maçı\n            (şampiyon. eşitlik bozma). Toplamda 21,5'un altında bahis yapın. Maç skoru 6:3;\n            3:6; 4:10 puan. Toplam 6 + 3 + 3 + 6 + 4 + 10 = 32 olacaktır.\n          </span>\n        </p>\n        <p>\n          <span>\n            Bazı turnuvalarda süper eşitlik bozucu (şampiyonluk eşitliği bozucu) oynanır\n            karar seti yerine. Oyuncu dikkate alınacak\n            maçın galibi (çift), şu şartla 10 puan kazanan ilk kişi:\n            2 puan daha farkla gol atıyor\n          </span>\n        </p>\n        <p>\n          <span>\n            9. “Set bazında skor” bahisi. “Spor” bölümündeki ilgili bahisler\n            2:0, 2:1 vb. başlıklı.\n          </span>\n        </p>\n        <p>\n          <span>\n            10. “Kazanan” bahisi. Kazanan tenisçidir (takım), birinci olur\n            turnuvada yerinizi alın. Bir tenis oyuncusu yarışmaya katılmayı reddederse\n            Turnuva başlamadan önce, bahisler şu şekilde sonuçlandırılacaktır:\n            oran 1.\n          </span>\n        </p>\n        <p>\n          <span>\n            11. “Oyunu kazan” bahisi. Kazanacak Tenisçinin Seçilmesi Belirtildi\n            oyun. Oyunların sürekli numaralandırılması yalnızca içinde geçerlidir.\n            set. İkinci setin skoru 6:1 olan “8. oyun 2. set” bahisi\n            Sekizinci maç olmadığı için 1 oranla sonuçlandırılacak.\n            \n          </span>\n        </p>\n        <p>\n          <span>12. Tie-breakler ayrı bir oyun olarak sayılır.</span>\n        </p>\n        <p>\n          <span>\n            “1/2 farklı skorla kazanır” bahisi zaferi varsayar\n            Skor 6:6 olduktan sonra eşitlik bozmada oyunculardan birinin oranı (veya\n            sonrasında süper bir eşitlik bozma\n          </span>\n        </p>\n        <p>\n          <span>Örnek: Klein – Kleck. “1 farklı skorla kazanacak” bahisi:</span>\n        </p>\n        <p>\n          <span>- Tie-break 7:3 skoruyla sona erdi - bahis kaybedildi</span>\n        </p>\n        <p>\n          <span>\n            - Tie-break 8:6 skoruyla sona erdi - bahis kazandı çünkü Oyuncu\n            Skor 6:6 olduktan sonra 1 galibiyet.\n          </span>\n        </p>\n        <p>\n          <strong>21. FLORBOL</strong>\n        </p>\n        <p>\n          <span>\n            1. Florbol, kapalı alanda sert bir sahada oynanan bir tür çarpıklıktır.\n            delikli plastik bir topla.\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Tüm bahisler ana maçın sonundaki sonuca göre sonuçlandırılır.\n            süresi (60 dakikalık oyun süresi, 20 dakikalık üç periyot)\n          </span>\n        </p>\n        <p>\n          <span>\n            Bahisçi yanlış sürenin hatalı olmasından sorumlu değildir.\n            maç. “Spor” ve Canlı bölümlerde belirtilen veriler gösterge niteliğindedir.\n            Müşteri resmi kaynaklardan kuralları kontrol etmelidir.\n          </span>\n        </p>\n        <p>\n          <span>\n            3. Sadece uzatmalar ve penaltı atışları dikkate alınır\n            Aşağıdaki bahisler hesaplanırken: “Bir sonrakine ilerleme\n            tur”, “Turnuvada galibiyet”\n          </span>\n        </p>\n        <p>\n          <strong>22. FUTBOL</strong>\n        </p>\n        <p>\n          <span>\n            1. Futbol maçlarına (kupa maçları dahil) bahisler kabul edilir.\n            Yönetmeliklerin öngördüğü ana oyun süresi (90 dakika)\n            oyun, 2 yarı 45 dakika artı maçın uzatma süresi), eğer\n            “Spor” bölümü aksini belirtmemektedir (“ekstra\n          </span>\n        </p>\n        <p>\n          <span>\n            Uzatmalar ve penaltı atışları yalnızca \"İlerleme\" bahislerine dahil edilir\n            bir sonraki tura çıkma”, “Başka bir lige yükselme”, “Turnuvayı kazanma”\n            ve benzeri.\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Tüm bahislerin geçerli olabilmesi için maçın 80 dakikasının oynanmış olması gerekmektedir.\n            Bahis sonuçlarının önceden açıkça belirlendiği durumlar hariç\n            o sırada maç durduruldu.\n          </span>\n        </p>\n        <p>\n          <span>3. Hazırlık maçlarının formatı.</span>\n        </p>\n        <p>\n          <span>\n            Gençler hazırlık maçlarının süresine ilişkin FIFA düzenlemeleri:\n          </span>\n        </p>\n        <p>\n          <span>\n            - U18, U17, U16, U15 takımları için - 80 dakika (40 dakikanın iki yarısı)\n          </span>\n        </p>\n        <p>\n          <span>\n            - U14 takımları için - 70 dakika (her biri 35 dakikalık iki yarı)\n            bahisler geçerliydi, maçın 70 dakikası geçmiş olmalı\n          </span>\n        </p>\n        <p>\n          <span>\n            - U13 ve U12 takımları için - 60 dakika (her biri 30 dakikalık iki yarı)\n            Bahislerin geçerli olması için maçın 60 dakikasının oynanması gerekir\n          </span>\n        </p>\n        <p>\n          <span>\n            Dostluk maçlarında kurallar müsabakaların başlamasından önce kabul edilir.\n            turnuva. Dostluk maçlarına bahis yapmadan önce şunu netleştirmelisiniz:\n            oyunun kuralları bağımsız\n          </span>\n        </p>\n        <p>\n          <span>\n            4. Dünya Kupası için “Turnuvayı daha üst sırada bitirmek” bahisleri\n            ve UEFA Avrupa Şampiyonası etaplara göre hesaplanacak\n            takımlar nereye kadar\n          </span>\n        </p>\n        <p>\n          <span>\n            5. En çok gol atan takıma veya -\n            Dünya Kupası ve UEFA Avrupa Şampiyonası, - gol atan takım başına\n            (kaçırılan) en fazla (en az) gol sayısı dikkate alınarak hesaplanır\n            Uzatma süreleri dikkate alınır ancak maç sonrası cezalar hariçtir.\n            Takımların eşit sayıda gol atması (veya yemesi) halinde bahisler sonuçlandırılır\n            1 oranla.\n          </span>\n        </p>\n        <p>\n          <span>\n            6. \"Uzatmalar\" olarak işaretlenen futbol maçlarına oynanan bahisler maç sonrası değildir\n            cezalar dikkate alınır. Maç sonrası penaltılara bahis yapmak\n            ayrı ayrı kabul edilir.\n          </span>\n        </p>\n        <p>\n          <span>\n            7. “İlk korneri takım atacak” diye bahis yapın. Belirlemek gerekli\n            ilk hangi takım olacak\n          </span>\n        </p>\n        <p>\n          <span>\n            8. \"Takım daha fazla korner kullanacak\" diye bahis yapın. Belirlemek gerekli\n            Hangi takım daha fazla korner kullanacak?\n          </span>\n        </p>\n        <p>\n          <span>\n            9. \"Alt/üst korner sayısı\" üzerine bahis yapın. Belirlemek gerekli\n            Önerilen değerden daha fazla veya daha az köşeler verilecektir.\n            Maçın seyri her iki takım tarafından da belirlendi.\n          </span>\n        </p>\n        <p>\n          <span>\n            10. Sarı kartlara yapılan bahisler. Toplam sarı kartlar ve sarı handikap kartları\n            - Sadece saha oyuncuları ve kalecilere uyarılar. Sayarken\n            Bir maçtaki sarı kart sayısı, uyarının tekrarlanmasıyla otomatik olarak sonuçlanır\n            Oyuncunun sahalardan çıkarılması dikkate alınmaz. Sarı\n            ve finalden sonra saha oyuncularına ve kalecilere gösterilen kırmızı kartlar\n            Oran hesaplamalarında düdük dikkate alınmayacaktır.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            11. Sarı ve kırmızı kartlara bahisler (kısaltılmış adı JK/K veya “kartlar”)\n            şu şekilde sayılır: sarı kart 1 kart, kırmızı kart 2 sarı\n            kartlar. Sarıyı tekrarla kart dikkate alınmaz ve bir kırmızı kart olarak sayılır.\n            Yani bir oyuncunun maç başına toplamda en fazla 3 kartı olabilir.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            12. Sarı ve kırmızı kart sayısı, korner sayısı, halter vuruşları\n            ve çapraz çubuk video yayını ile belirlenir. Eğer yayın\n            gerçekleştirilmediyse veya kesintiye uğradıysa sarı/kırmızı sayısı\n            kartlar ve köşeler resmi bilgi kaynaklarından alınmıştır.\n            Resmi kaynağa göre 46. yüzyılda yapılan oyuncu değişikliği\n            dakika içinde, uzlaşma amacıyla, süre içinde tamamlanmış sayılır.\n            ara. Yeniden gönderen köşe, hesaplama amacıyla dikkate alınır\n            biri olarak. Toplam hesaplamada Yalnızca köşeler için\n          </span>\n        </p>\n        <p>\n          <span>\n            13. Maç sonrası penaltılara oynanan bahisler. Maç sonrası penaltılarda ise beşinci\n            penaltı alınmadıysa aşağıdaki bahisler iade edilir:\n          </span>\n        </p>\n        <p>\n          <span>- “2. takım beşinci penaltıyı alamayacak”</span>\n        </p>\n        <p>\n          <span>- “2. takım beşinci penaltıyı atacak”</span>\n        </p>\n        <p>\n          <span>\n            14. Bahis “İlk golü oyuncu atar ve takım kazanır\n            bir puanla.” İlk golü atan oyuncuyu tahmin etmeniz gerekiyor\n            ve maçın normal süresi sonundaki skor (sakatlıklar dahil)\n            zaman). Oyuncu maçta yer almamışsa veya maça girmişse\n            sahada ilk gol atıldıktan sonra bahis sonuçlandırılır\n            1 oranla. İlk gol kendi kalesine atılırsa (kendi kalesine atılan gol),\n            o zaman bahis bu golü atan oyuncu üzerine yapılır ve sonuçlandırılır\n            1 oranla. Maç ilk golün ardından yarıda kesilirse\n            puanlandıysa ve kurallarda belirtilen süreler tamamlanmadıysa,\n            bu golü atan oyuncuya bahis\n          </span>\n        </p>\n        <p>\n          <span>Örnek 1:</span>\n        </p>\n        <p>\n          <span>\n            Bahis 1 “İlk golü Adam Lallana atacak ve 1. Takım kazanacak\n            skor 1-0”\n          </span>\n        </p>\n        <p>\n          <span>\n            Bahis 2 “İlk golü Dejan Lovren atacak ve 1. Takım atacak\n            1-0 skorla kazandık”\n          </span>\n        </p>\n        <p>\n          <span>Durum 1:</span>\n        </p>\n        <p>\n          <span>\n            İlk golü Adam Lallana attı ve 1. Takım 1-0 kazandı:\n          </span>\n        </p>\n        <p>\n          <span>- bahis 1 kazandı</span>\n        </p>\n        <p>\n          <span>- bahis 2 kaybedildi</span>\n        </p>\n        <p>\n          <span>Örnek 2:</span>\n        </p>\n        <p>\n          <span>\n            Adam Lallana sahaya girmedi ve 1. Takım skorla kazandı\n          </span>\n        </p>\n        <p>\n          <span>- bahis 1 iade edilir</span>\n        </p>\n        <p>\n          <span>- bahis 2 kaybedildi</span>\n        </p>\n        <p>\n          <span>\n            15. Kartlar. İstatistikler. Bahisler meydana gelen olaylara göre sonuçlandırılır\n            Oyunun ana saatinde. Yalnızca kartlar sayıldı\n            Sahadaki oyunculara gösterildi.\n          </span>\n        </p>\n        <p>\n          <span>\n            “İlk kart” bahisi. Bahisler, sırasında meydana gelen olaylara göre hesaplanır.\n            Maçta ayrılan süre. Kırmızı veya sarı kartlar lazım\n            belirlenen periyot maç süresi içerisinde gösterilecektir. Kart\n            uyarıyla sonuçlanan olay dikkate alınmaz\n            (veya çıkarma) belirli bir süre içinde gerçekleşti, ancak kart\n            belli bir süre sonra gösterilir.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            “Toplam kartlar” bahisi. Bahisler için ek (telafi edilmiş) süre.\n            Aksi durumlar dışında ek süre dikkate alınmaz\n            belirtti. İkinci ihlal için yalnızca bir kart sayılacaktır.\n            Yani, sarı kartın ardından hemen ardından kırmızı kart gelirse,\n            o zaman yalnızca bir tanesi kart sayılacaktır. Buna göre maksimum kart sayısı\n            bir oyuncunun alabileceği ikiye eşittir.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            “Son kart” bahisi. Maç kartlarında hiçbiri gösterilmiyorsa kazanan\n            sonuç “Kart yok” olur. Diğer tüm bahisler kaybeder. İki veya daha fazla oyuncu varsa\n            aynı durumdaysa bahis şu şekilde hesaplanacaktır:\n            gösterilen son kartta.\n          </span>\n        </p>\n        <p>\n          <span>\n            16. Bahis \"1. Takım 78:00 dakikadan önce 1 numaralı golü atacaktır -\n            Evet\" — 1. takımın gol atacağını belirlemeniz gerekir\n            Bu dönemdeki ilk gol. Eğer gol 78'inde atılırsa\n            dakika, bu hesaplanırken dikkate alınacaktır\n          </span>\n        </p>\n        <p>\n          <span>\n            17. “Penaltı ve ihraç (evet)” bahisi. Bahis hesaplanacak\n            Oyun hem penaltı hem de silme içeriyorsa kazanır.\n          </span>\n        </p>\n        <p>\n          <span>\n            18. “Oyuncu gol atacak…” bahisi. Bahis olacak\n            Oyuncu sahaya girip gol attığında hesaplanan kazanç\n            bir amaç. Kendi kalesine atılan gol\n          </span>\n        </p>\n        <p>\n          <span>\n            - bahis maç öncesinde yapılmışsa - eğer oyuncu maça girmemişse\n            alanı, daha sonra getiri ile oran hesaplanır. Fiyatlar yalnızca geçerlidir\n            ana kadrodaki oyuncular için, yani eğer oyuncu yedek olarak gelmişse\n            ve maç öncesinde bahisler verildiyse bu tür kuponlar hesaplanacaktır.\n            dönüş\n          </span>\n        </p>\n        <p>\n          <span>\n            - bahis canlı olarak oynandı - eğer oyuncu sahaya girerse, o zaman\n            Bahisler attığı gol sayısına göre sonuçlandırılır\n          </span>\n        </p>\n        <p>\n          <strong>23.FUTSAL</strong>\n        </p>\n        <p>\n          <span>\n            1. Tüm bahisler ana maçın sonundaki sonuca göre sonuçlandırılır.\n            süre (40 dakikalık oyun süresi, her biri 20 dakikalık iki devre).\n          </span>\n        </p>\n        <p>\n          <span>\n            Bahis şirketi yanlış sürenin hatalı olmasından sorumlu değildir.\n            maç. “Spor” ve Canlı bölümlerde belirtilen veriler gösterge niteliğindedir.\n            Müşteri resmi kaynaklardaki kuralları kontrol etmelidir.\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Uzatmalar ve 6 metreden penaltı atışları\n            yalnızca aşağıdaki bahislerde dikkate alınır: bir sonrakine ilerleme\n            tur, bir turnuvayı kazanmak ve\n          </span>\n        </p>\n        <p>\n          <span>\n            3. Maç başlamış ancak tamamlanmamışsa tüm bahisler geçerli sayılacaktır.\n            Sonucu kesin olan bahisler hariç, 1 oranla sonuçlandırılır\n            maç durduruluncaya kadar belirlenir.\n          </span>\n        </p>\n        <p>\n          <span>\n            4. Bir maçın resmi olarak tamamlanmış sayılması için, oyunun\n            en az 35 dakika sürmelidir. Bu durumda, tüm bahisler esas alınarak hesaplanır.\n            maç anındaki sonuçtan\n          </span>\n        </p>\n        <p>\n          <strong>24. ÇİM HOKEYİ</strong>\n        </p>\n        <p>\n          <span>\n            1. Tüm bahisler ana maçın sonundaki sonuca göre sonuçlandırılır.\n            süresi (70 dakikalık oyun süresi, 35 dakikalık iki devre veya\n            17 dakika 30 saniyelik dört periyot).\n          </span>\n        </p>\n        <p>\n          <span>\n            Bahis şirketi yanlış sürenin hatalı olmasından sorumlu değildir.\n            maç. “Spor” ve Canlı bölümlerde belirtilen veriler gösterge niteliğindedir.\n            Müşteri resmi kaynaklardaki kuralları kontrol etmelidir.\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Uzatmalar ve penaltı atışları yalnızca aşağıdaki bahislerde dikkate alınır:\n            bir sonraki tura geçmek, turnuvayı kazanmak ve benzeri.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            3. Maç başlamış ancak tamamlanmamışsa tüm bahisler geçerli sayılacaktır.\n            Sonucu kesin olan bahisler hariç, 1 oranla sonuçlandırılır\n            maç durduruluncaya kadar belirlenir.\n          </span>\n        </p>\n        <p>\n          <span>\n            4. Bir maçın resmi olarak tamamlanmış sayılması için, oyunun\n            en az 60 dakika sürmelidir. Bu durumda, tüm bahisler esas alınarak hesaplanır.\n            maç anındaki sonuçtan\n          </span>\n        </p>\n        <p>\n          <span>\n            5. Kapalı hokey, bir tür kapalı çim hokeyi tesisidir.\n            Maç 20'şer dakikalık iki devreden oluşuyor.\n          </span>\n        </p>\n        <p>\n          <strong>25. BUZ HOKEYİ</strong>\n        </p>\n        <p>\n          <span>\n            1. “Spor” bölümündeki bahisler normal süre için (60 dakika) kabul edilir.\n            oyunlar, 20 dakikalık 3 periyot) aksi belirtilmedikçe (konu\n            ek süre dikkate alınarak \"uzatmadan itibaren\" olarak işaretlenen ek süreye kadar\n            süre ve penaltı atışları “uzatma ve penaltılarla birlikte” olarak işaretlenmiştir).\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Canlı bölümündeki bahisler yalnızca normal süre için kabul edilir;\n            notlar maçın farklı bir bölümünü göstermiyor. Bahisler\n            Canlı bölümünde \"Uzatma\" olarak işaretlenen maçlar yalnızca uzatmalar sayılır\n            ve çatışmayı dahil etmeyin\n          </span>\n        </p>\n        <p>\n          <span>KHL ve NHL maçlarına canlı bahisler kabul edilir:</span>\n        </p>\n        <p>\n          <span>- normal süre için</span>\n        </p>\n        <p>\n          <span>\n            - normal süre için, ek süre dikkate alınarak (\"itibaren\" olarak işaretlenmiştir)\n            fazla uzatma\")\n          </span>\n        </p>\n        <p>\n          <span>\n            - normal süre için, uzatmalar ve penaltı atışları dikkate alınarak (\n            \"Uzatma ve penaltı atışlarıyla işaretlendi\")\n          </span>\n        </p>\n        <p>\n          <span>\n            Örnek 1: Buffalo Sabres - Toronto Akçaağaç Yaprakları (ek olarak)\n            zaman ve çatışmalar). Bu durumda maça yapılan bahisler kabul edilir.\n            Uzatmalar ve penaltı atışları da dahil olmak üzere normal sürede. Hesap eşleşmesi\n            2:3 (1:0, 1:1, 0:1, 0:0, 0:1). Tüm bahisler şu esaslara göre sonuçlandırılacaktır:\n            son skor 2:3. Bu maçta toplam gol sayısı 5 olacaktır.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            Örnek 2. Buffalo Sabres - Toronto Akçaağaç Yaprakları (Uzatma ile). bunda\n            Maçtaki durum bahisleri normal süre için kabul edilir,\n            ek süreyi dikkate alarak. Oyunun son puanı\n            2:2 puan olarak kabul edilecektir (1:0, 1:1, 0:1; 0:0). için toplam hedefler\n            bu maç 4 olacaktır. Takımın galibiyetine bahisler\n          </span>\n        </p>\n        <p>\n          <span>\n            Örnek 3. Buffalo Sabres - Toronto Akçaağaç Yaprakları. Bu durumda oranlar\n            yalnızca normal saatlerde kabul edilir. Bu maçın son puanı\n            puan 2:2 (1:0, 1:1, 0:1) olarak değerlendirilecektir. Bunun için toplam hedefler\n            oyun 4'e eşit olacaktır. 1. ve 1. takımın galibiyeti üzerine bahisler\n          </span>\n        </p>\n        <p>\n          <span>\n            3. Maç başlamış ancak tamamlanmamışsa tüm bahisler geçerli sayılacaktır.\n            Sonucu kesin olan bahisler hariç, 1 oranla sonuçlandırılır\n            maç durduruluncaya kadar belirlenir.\n          </span>\n        </p>\n        <p>\n          <span>\n            4. Bahislerin geçerli sayılması için oyunun en az sürmesi gerekir.\n            55 dakika. Bu durumda tüm bahisler sonuca göre hesaplanır.\n            o sırada maç durduruldu.\n          </span>\n        </p>\n        <p>\n          <span>\n            5. Takımlar NHL, AHL, CHL, OHL, WHL, Doğu Hokey Ligi kıyıları\n            Kuzey Amerika'nın konumu düz bir çizgi dizisinde bulunabilir\n            (ev sahipleri - misafirler) ve bunun tersi. Geri ödeme yapılmaması durumunda\n            ters emirlerde.\n          </span>\n        </p>\n        <p>\n          <span>\n            6. “Toplam” bahis. Çatışmalar da dahil olmak üzere sıradaki disk sayısı\n            Kazanan takımın penaltı atışlarında attığı toplam gol sayısı\n            hesaplama 1 gol olarak alınır, atılan gol sayısı ise\n            Kaybeden takımın penaltı atışları 0 olarak alınır.\n          </span>\n        </p>\n        <p>\n          <span>\n            7. “1. ve 7. dakikalar arasında gol” bahisi yapın. Gol atılırsa\n            7 dakika 00 saniyede atılmış sayılıyor\n          </span>\n        </p>\n        <p>\n          <span>\n            8. Aşağıdaki bahisler kaydedilen sonuca göre sonuçlandırılır veya\n            spor etkinliğinin resmi organizatörlerinin sıralamaları: “Daha yüksek\n            Turnuva sonunda”, “Şampiyonluk kazananı”, “Kazanan\n            Grupta”, “Atılan Puanlar”, “Atılan Goller” ve “Kaçırılan Goller”.\n          </span>\n        </p>\n        <p>\n          <span>\n            9. “Sonuç ve Toplam Alt/Üst” bahisi. Belirlemek gerekli\n            maçı hangi takım kazanacak ve kaç gol atılacak (devamı\n            veya belirtilen miktardan daha az). NHL ve KHL maçlarına bahisler,\n            ve ayrıca diğer şampiyonaların ve uluslararası maçların maçları için\n            düzenli olarak kabul edilen yarışmalar\n          </span>\n        </p>\n        <p>\n          <span>\n            10. \"3 (5 vb.) puan için yarış\" bahisine girin. Belirlemek gerekli\n            Belirtilen sayıda puanı ilk hangi takım alacak?\n            bir maçta. Eğer bir takım herhangi bir nedenle oyuna devam etmeyi reddederse\n            Rakibinin belirlenen sayıda puanı almasına kadar,\n            Bahisler 1 oranla hesaplanır.\n          </span>\n        </p>\n        <p>\n          <span>\n            11. \"2. Takım uzatmalarda kazanır - Hayır\" bahisine girin. Oran varsa kazanacak\n            Maçta uzatma süresi olmadı veya 2. takım uzatmalarda kaybetti. Bahisler\n            çatışmada zafer de benzer şekilde hesaplanır.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            12. \"Uzatmalarda kazan\" bahisi. Kazanan ekstra olarak karar vermeli\n            zaman (OT).\n          </span>\n        </p>\n        <p>\n          <span>Oyun skoru (0:0; 1:1; 1:0) – yenilgi.</span>\n        </p>\n        <p>\n          <span>Oyun skoru (0:0; 1:1; 0:0; 0:1) – galibiyet.</span>\n        </p>\n        <p>\n          <span>Oyun skoru (0:0; 1:1; 0:0; 0:0; 1:0) – kayıp.</span>\n        </p>\n        <p>\n          <strong>26. KASELER</strong>\n        </p>\n        <p>\n          <span>\n            1. Bahisler set ve maçlara kabul edilir. Tüm setler oynanmalı\n            maç. Herhangi bir nedenle kazanan önceden belirlenirse\n            Maçın sonunda setlere yapılan bahisler, oyunun devam ettiği durumlar haricinde geçersizdir.\n            sonucu etkiler.\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Kazanan tüm setler tamamlanmadan belirlenirse bahisler\n            maçın galibi resmi makamlara göre hesaplanır\n            sonuç, en az bir tarafın oynanması şartıyla\n          </span>\n        </p>\n        <p>\n          <span>\n            3. Girilen tüm oyuncuların maç başlamadan önce değiştirilmesi durumunda,\n            tüm bahisler geçersiz sayılır.\n          </span>\n        </p>\n        <p>\n          <strong>27. FORMULA 1, MOTOSİKLET YARIŞI, SPEEDWAY</strong>\n        </p>\n        <p>\n          <span>\n            1. Yarış tamamlanmadıysa ve resmi sonuçlar\n            açıklanmadığı takdirde, sonucu belirlenen bahisler hariç tüm bahisler geçersizdir.\n            zaten açıkça belirlenmiştir.\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Bahisler Uluslararası derecelendirmeye göre hesaplanır.\n            Otomobil Birliği (FIA), son yarıştan hemen sonra\n          </span>\n        </p>\n        <p>\n          <span>\n            3. “Birebir” bahisi. Bunlardan hangisinin belirlenmesi gereklidir\n            belirtilen bisikletçilerden ikisi daha iyi performans gösterecek. Bitiren binici\n            Yarışta en iyi sırayı alan (son sıralamada), değerlendirmeye alınır\n            daha iyi performans göstermiş olmak.\n          </span>\n        </p>\n        <p>\n          <span>\n            Bahislerin geçerli olması için her iki sürücünün de yarışa başlaması gerekir. Her iki sürücü de\n            bitirilemezse, bahisler tamamlananlara göre hesaplanır\n            tur. Her iki sürücünün de yarış dışı kalması durumunda yarışı tamamlayan sürücü\n            Çoğu turun daha iyi gerçekleştirildiği kabul edilir. Her iki sürücü de çıkarsa\n            yarışta tamamlanan tur sayısı berabere kalır, bahisler hesaplanır\n            1 oranla. Sürücü hızlı turu tamamlayamazsa\n            (yeterlilik süresini karşılamamışsa), yeri şu şekilde belirlenir:\n            son başlangıç pozisyonları.\n            \n          </span>\n        </p>\n        <p>\n          <strong>28. Counter-Strike: GO</strong>\n        </p>\n        <p>\n          <span>\n            1. Oranlar resmi olarak yayınlanan sonuçlara göre hesaplanır.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            2. Yaklaşan maçlar listesinde yanlışlıklar varsa, rezerve ederiz\n            bahisleri iptal etme hakkını saklı tutar.\n          </span>\n        </p>\n        <p>\n          <span>\n            3. Teknik zafer veya oyunun yarıda bırakılması durumunda, tüm oyuncular\n            sonuçlanmamış bahisler geçersizdir.\n          </span>\n        </p>\n        <p>\n          <span>\n            4. Bir maç veya harita tamamlanmazsa, ödenmemiş tüm bahisler iptal edilir.\n            iptal edildi.\n          </span>\n        </p>\n        <p>\n          <span>\n            4. Bağlantı kopması veya teknik bir sorun nedeniyle bir maç veya harita tekrar oynatılırsa\n            oynatıcıyla ilgili olmayan sorunların tümü Kararsız\n            bahisler geçersiz olacaktır. Bir haritayı tekrar oynatmak veya eşleştirmek için Ayrı ücretler uygulanacaktır.\n            verildi.\n          </span>\n        </p>\n        <p>\n          <span>\n            5. Standart kart sayısının değişmesi veya belirtilenden farklı olması durumunda\n            Bahis koymak için bahisleri iptal etme hakkımız saklıdır.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            6. Sunulan tüm pazarlar, aksi belirtilmedikçe uzatmalarla çözülecektir.\n            belirtti.\n          </span>\n        </p>\n        <p>\n          <strong>29.Dota2</strong>\n        </p>\n        <p>\n          <span>\n            1. Oranlar resmi olarak yayınlanan sonuçlara göre hesaplanır.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            2. Yaklaşan maçlar listesinde yanlışlıklar varsa, rezerve ederiz\n            bahisleri iptal etme hakkını saklı tutar.\n          </span>\n        </p>\n        <p>\n          <span>\n            3. Teknik zafer veya oyunun yarıda bırakılması durumunda, tüm oyuncular\n            sonuçlanmamış bahisler geçersizdir.\n          </span>\n        </p>\n        <p>\n          <span>\n            4. Bir maç veya harita tamamlanmazsa, ödenmemiş tüm bahisler iptal edilir.\n            iptal edildi.\n          </span>\n        </p>\n        <p>\n          <span>\n            5. Bağlantı kopması veya teknik bir sorun nedeniyle bir maç veya harita tekrar oynatılırsa\n            oynatıcıyla ilgili olmayan sorunların tümü Kararsız\n            bahisler geçersiz olacaktır. Bir haritayı tekrar oynatmak veya eşleştirmek için Ayrı ücretler uygulanacaktır.\n            verildi.\n          </span>\n        </p>\n        <p>\n          <span>\n            6. Standart kart sayısının değişmesi veya belirtilenden farklı olması durumunda\n            Bahis koymak için bahisleri iptal etme hakkımız saklıdır.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            7. “Harita – ilk kalkan” bahsi kimin seçeceğine göre hesaplanır\n            Aegis'e çık ve Roshan'ı öldürme.\n          </span>\n        </p>\n        <p>\n          <span>\n            8. “Harita – ilk kule” bahsi. Bir kuleyi yok etmenin her yöntemi önemlidir\n            (sürüngenler tarafından kulenin yok edilmesi, rakibin kulenin yok edilmesi veya\n            Oyuncunuz tarafından kulenin reddedilmesi).\n          </span>\n        </p>\n        <p>\n          <span>\n            9. “Harita ilk kışladır” bahisi. Kışlayı yok etmenin herhangi bir yöntemi\n            sayımlar (kışlaların sürüngenler tarafından tahrip edilmesi,\n            Kışlanın rakibini ya da barakayı sizin tarafınızdan inkar edin\n          </span>\n        </p>\n        <p>\n          <strong>30. EFSANELER LİGİ</strong>\n        </p>\n        <p>\n          <span>\n            1. Oranlar resmi olarak yayınlanan sonuçlara göre hesaplanır.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            2. Yaklaşan maçlar listesinde yanlışlıklar varsa, rezerve ederiz\n            bahisleri iptal etme hakkını saklı tutar. Teknik zafer durumunda\n            veya Oynamayı reddederseniz, sonuçlandırılmamış tüm bahisler geçersiz olacaktır.\n          </span>\n        </p>\n        <p>\n          <span>\n            3. Teknik zafer veya oyunun yarıda bırakılması durumunda, tüm oyuncular\n            sonuçlanmamış bahisler geçersizdir.\n          </span>\n        </p>\n        <p>\n          <span>\n            4. Bir maç veya harita tamamlanmazsa, ödenmemiş tüm bahisler iptal edilir.\n            iptal edildi.\n          </span>\n        </p>\n        <p>\n          <span>\n            5. Bağlantı kopması veya teknik bir sorun nedeniyle bir maç veya harita tekrar oynatılırsa\n            oynatıcıyla ilgili olmayan sorunların tümü Kararsız\n            bahisler geçersiz olacaktır. Bir haritayı tekrar oynatmak veya eşleştirmek için Ayrı ücretler uygulanacaktır.\n            verildi.\n          </span>\n        </p>\n        <p>\n          <span>\n            6. Standart kart sayısının değişmesi veya belirtilenden farklı olması durumunda\n            Bahis koymak için bahisleri iptal etme hakkımız saklıdır.\n            \n          </span>\n        </p>\n      </div>\n";
